class Solution {
public:
    void nextPermutation(vector<int>& nums) {
        int n = nums.size();
        if (n <= 1) return;
        vector<vector<int>> all;
        vector<int> sorted = nums;
        sort(sorted.begin(), sorted.end());
        vector<int> path;
        vector<bool> used(n, false);
        dfs(sorted, used, path, all);
        sort(all.begin(), all.end());
        int idx = 0;
        for (int i = 0; i < (int)all.size(); ++i) {
            if (all[i] == nums) { idx = i; break; }
        }
        nums = all[(idx + 1) % all.size()];
    }
private:
    void dfs(vector<int>& sorted, vector<bool>& used, vector<int>& path, vector<vector<int>>& all) {
        if (path.size() == sorted.size()) { all.push_back(path); return; }
        for (int i = 0; i < (int)sorted.size(); ++i) {
            if (used[i]) continue;
            if (i > 0 && sorted[i] == sorted[i-1] && !used[i-1]) continue;
            used[i] = true;
            path.push_back(sorted[i]);
            dfs(sorted, used, path, all);
            path.pop_back();
            used[i] = false;
        }
    }
};

