from typing import List
class Solution:
    def nextPermutation(self, nums: List[int]) -> None:
        from itertools import permutations
        n = len(nums)
        if n <= 1:
            return
        cur = tuple(nums)
        all_perms = sorted(set(permutations(nums)))
        idx = all_perms.index(cur)
        nxt = all_perms[(idx + 1) % len(all_perms)]
        for i in range(n):
            nums[i] = nxt[i]

