class Solution {
    public void nextPermutation(int[] nums) {
        int n = nums.length;
        if (n <= 1) return;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        List<List<Integer>> all = new ArrayList<>();
        boolean[] used = new boolean[n];
        dfs(sorted, used, new ArrayList<>(), all);
        Collections.sort(all, (a, b) -> {
            for (int i = 0; i < a.size(); i++) {
                if (!a.get(i).equals(b.get(i))) return a.get(i) - b.get(i);
            }
            return 0;
        });
        int idx = 0;
        for (int i = 0; i < all.size(); i++) {
            boolean same = true;
            for (int j = 0; j < n; j++) if (all.get(i).get(j) != nums[j]) same = false;
            if (same) { idx = i; break; }
        }
        List<Integer> nxt = all.get((idx + 1) % all.size());
        for (int i = 0; i < n; i++) nums[i] = nxt.get(i);
    }
    private void dfs(int[] sorted, boolean[] used, List<Integer> path, List<List<Integer>> all) {
        if (path.size() == sorted.length) { all.add(new ArrayList<>(path)); return; }
        for (int i = 0; i < sorted.length; i++) {
            if (used[i]) continue;
            if (i > 0 && sorted[i] == sorted[i-1] && !used[i-1]) continue;
            used[i] = true;
            path.add(sorted[i]);
            dfs(sorted, used, path, all);
            path.remove(path.size() - 1);
            used[i] = false;
        }
    }
}

